package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"strings"
)

func main() {
	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "usage: jobforge <plan|run> --spec <path> [flags]")
		os.Exit(2)
	}

	switch os.Args[1] {
	case "plan":
		os.Exit(runPlan(os.Args[2:]))
	case "run":
		os.Exit(runRun(os.Args[2:]))
	default:
		fmt.Fprintln(os.Stderr, "usage: jobforge <plan|run> --spec <path> [flags]")
		os.Exit(2)
	}
}

func runPlan(args []string) int {
	fs := flag.NewFlagSet("plan", flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	specPath := fs.String("spec", "", "path to spec file")
	format := fs.String("format", "text", "output format: json|text")
	if err := fs.Parse(args); err != nil {
		return 2
	}
	if *specPath == "" {
		fmt.Fprintln(os.Stderr, "usage: jobforge plan --spec <path> [--format json|text]")
		return 2
	}
	if *format != "text" && *format != "json" {
		fmt.Fprintf(os.Stderr, "error: invalid format: %s\n", *format)
		return 2
	}

	spec, err := loadSpec(*specPath)
	if err != nil {
		printValidationError(err)
		return 2
	}

	levels := computeLevels(spec)
	switch *format {
	case "text":
		for i, names := range levels {
			fmt.Printf("level %d: %s\n", i, strings.Join(names, ", "))
		}
	case "json":
		out, err := json.Marshal(map[string][][]string{"levels": levels})
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: marshal: %s\n", err)
			return 2
		}
		os.Stdout.Write(out)
		fmt.Println()
	}
	return 0
}

func runRun(args []string) int {
	fs := flag.NewFlagSet("run", flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	specPath := fs.String("spec", "", "path to spec file")
	onFailure := fs.String("on-failure", "stop", "on failure behavior: stop|continue")
	resultsPath := fs.String("results", "", "path to results JSON file")
	if err := fs.Parse(args); err != nil {
		return 2
	}
	if *specPath == "" {
		fmt.Fprintln(os.Stderr, "usage: jobforge run --spec <path> [--on-failure stop|continue] [--results <path>]")
		return 2
	}
	if *onFailure != "stop" && *onFailure != "continue" {
		fmt.Fprintf(os.Stderr, "error: invalid on-failure: %s\n", *onFailure)
		return 2
	}

	spec, err := loadSpec(*specPath)
	if err != nil {
		printValidationError(err)
		return 2
	}

	return runSpec(spec, *onFailure, *resultsPath)
}

func printValidationError(err error) {
	if ve, ok := err.(*ValidationError); ok {
		fmt.Fprintf(os.Stderr, "error: %s: %s\n", ve.Code, ve.Message)
		return
	}
	fmt.Fprintf(os.Stderr, "error: %s\n", err)
}
