package main

import (
	"encoding/json"
	"fmt"
	"os"
	"regexp"
	"sort"
	"strings"
)

type Job struct {
	Index   int
	Name    string
	Command string
	Deps    []string
	Workdir string
	Env     map[string]string
}

type Spec struct {
	Jobs   []*Job
	ByName map[string]*Job
}

type ValidationError struct {
	Code    string
	Message string
}

func (e *ValidationError) Error() string {
	return e.Code + ": " + e.Message
}

var (
	nameRegexp    = regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_-]*$`)
	envKeyRegexp  = regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_]*$`)
)

func loadSpec(path string) (*Spec, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, &ValidationError{Code: "spec_not_found", Message: fmt.Sprintf("cannot read spec: %s", path)}
	}

	var top map[string]json.RawMessage
	if err := json.Unmarshal(data, &top); err != nil || top == nil {
		return nil, &ValidationError{Code: "spec_parse", Message: "top-level JSON must be an object"}
	}

	rawJobs, ok := top["jobs"]
	if !ok {
		return nil, &ValidationError{Code: "spec_parse", Message: "missing jobs"}
	}

	var jobsRaw []json.RawMessage
	if err := json.Unmarshal(rawJobs, &jobsRaw); err != nil || jobsRaw == nil {
		return nil, &ValidationError{Code: "spec_parse", Message: "jobs must be an array"}
	}

	var unknownTop []string
	for k := range top {
		if k != "jobs" {
			unknownTop = append(unknownTop, k)
		}
	}
	if len(unknownTop) > 0 {
		sort.Strings(unknownTop)
		return nil, &ValidationError{Code: "unknown_field", Message: "unknown field: " + unknownTop[0]}
	}

	jobMaps := make([]map[string]json.RawMessage, len(jobsRaw))
	for i, raw := range jobsRaw {
		var m map[string]json.RawMessage
		if err := json.Unmarshal(raw, &m); err != nil || m == nil {
			return nil, &ValidationError{Code: "spec_parse", Message: fmt.Sprintf("jobs[%d] must be an object", i)}
		}
		jobMaps[i] = m
	}

	jobs := make([]*Job, len(jobMaps))
	for i, m := range jobMaps {
		job := &Job{
			Index:   i,
			Deps:    []string{},
			Env:     map[string]string{},
			Workdir: "/app",
		}

		if raw, ok := m["name"]; ok {
			var s string
			if err := json.Unmarshal(raw, &s); err != nil {
				return nil, &ValidationError{Code: "spec_parse", Message: fmt.Sprintf("jobs[%d].name must be a string", i)}
			}
			job.Name = s
		}
		if raw, ok := m["command"]; ok {
			var s string
			if err := json.Unmarshal(raw, &s); err != nil {
				return nil, &ValidationError{Code: "spec_parse", Message: fmt.Sprintf("jobs[%d].command must be a string", i)}
			}
			job.Command = s
		}
		if raw, ok := m["deps"]; ok {
			var arr []string
			if err := json.Unmarshal(raw, &arr); err != nil || arr == nil {
				return nil, &ValidationError{Code: "spec_parse", Message: fmt.Sprintf("jobs[%d].deps must be an array of strings", i)}
			}
			job.Deps = arr
		}
		if raw, ok := m["workdir"]; ok {
			var s string
			if err := json.Unmarshal(raw, &s); err != nil {
				return nil, &ValidationError{Code: "spec_parse", Message: fmt.Sprintf("jobs[%d].workdir must be a string", i)}
			}
			job.Workdir = s
		}
		if raw, ok := m["env"]; ok {
			env := map[string]string{}
			if err := json.Unmarshal(raw, &env); err != nil || env == nil {
				return nil, &ValidationError{Code: "spec_parse", Message: fmt.Sprintf("jobs[%d].env must be an object of strings", i)}
			}
			job.Env = env
		}
		jobs[i] = job
	}

	for i, m := range jobMaps {
		var unknown []string
		for k := range m {
			if !isKnownJobField(k) {
				unknown = append(unknown, k)
			}
		}
		if len(unknown) > 0 {
			sort.Strings(unknown)
			return nil, &ValidationError{Code: "unknown_field", Message: fmt.Sprintf("unknown field: jobs[%d].%s", i, unknown[0])}
		}
	}

	for _, job := range jobs {
		if _, ok := jobMaps[job.Index]["name"]; !ok {
			return nil, &ValidationError{Code: "invalid_name", Message: "invalid name: <missing>"}
		}
		if !nameRegexp.MatchString(job.Name) {
			return nil, &ValidationError{Code: "invalid_name", Message: "invalid name: " + job.Name}
		}
	}

	seen := map[string]bool{}
	for _, job := range jobs {
		if seen[job.Name] {
			return nil, &ValidationError{Code: "duplicate_name", Message: "duplicate name: " + job.Name}
		}
		seen[job.Name] = true
	}

	for _, job := range jobs {
		if _, ok := jobMaps[job.Index]["command"]; !ok {
			return nil, &ValidationError{Code: "invalid_command", Message: "invalid command for " + job.Name}
		}
		if job.Command == "" {
			return nil, &ValidationError{Code: "invalid_command", Message: "invalid command for " + job.Name}
		}
	}

	for _, job := range jobs {
		keys := make([]string, 0, len(job.Env))
		for k := range job.Env {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			if !envKeyRegexp.MatchString(k) {
				return nil, &ValidationError{Code: "invalid_env_key", Message: "invalid env key in " + job.Name + ": " + k}
			}
		}
	}

	spec := &Spec{Jobs: jobs, ByName: map[string]*Job{}}
	for _, job := range jobs {
		spec.ByName[job.Name] = job
	}

	for _, job := range jobs {
		for _, dep := range job.Deps {
			if _, ok := spec.ByName[dep]; !ok {
				return nil, &ValidationError{Code: "unknown_dep", Message: "unknown dep in " + job.Name + ": " + dep}
			}
		}
	}

	for _, job := range jobs {
		seenDeps := map[string]bool{}
		for _, dep := range job.Deps {
			if seenDeps[dep] {
				return nil, &ValidationError{Code: "duplicate_dep", Message: "duplicate dep in " + job.Name + ": " + dep}
			}
			seenDeps[dep] = true
		}
	}

	for _, job := range jobs {
		for _, dep := range job.Deps {
			if dep == job.Name {
				return nil, &ValidationError{Code: "self_dep", Message: "self dep: " + job.Name}
			}
		}
	}

	if err := detectCycle(spec); err != nil {
		return nil, err
	}

	return spec, nil
}

func isKnownJobField(k string) bool {
	switch k {
	case "name", "command", "deps", "workdir", "env":
		return true
	}
	return false
}

func computeLevels(spec *Spec) [][]string {
	level := map[string]int{}

	var dfs func(job *Job) int
	dfs = func(job *Job) int {
		if l, ok := level[job.Name]; ok {
			return l
		}
		maxDep := -1
		for _, dep := range job.Deps {
			l := dfs(spec.ByName[dep])
			if l > maxDep {
				maxDep = l
			}
		}
		level[job.Name] = maxDep + 1
		return level[job.Name]
	}

	for _, job := range spec.Jobs {
		dfs(job)
	}

	maxLevel := -1
	for _, l := range level {
		if l > maxLevel {
			maxLevel = l
		}
	}

	levels := make([][]string, maxLevel+1)
	for _, job := range spec.Jobs {
		levels[level[job.Name]] = append(levels[level[job.Name]], job.Name)
	}
	for _, names := range levels {
		sort.Strings(names)
	}
	return levels
}
