package main

import (
	"sort"
	"strings"
)

func detectCycle(spec *Spec) *ValidationError {
	adj := map[string][]string{}
	for _, job := range spec.Jobs {
		deps := append([]string(nil), job.Deps...)
		sort.Strings(deps)
		adj[job.Name] = deps
	}

	index := 0
	stack := []string{}
	onStack := map[string]bool{}
	indices := map[string]int{}
	low := map[string]int{}
	var sccs [][]string

	var strongconnect func(v string)
	strongconnect = func(v string) {
		indices[v] = index
		low[v] = index
		index++
		stack = append(stack, v)
		onStack[v] = true

		for _, w := range adj[v] {
			if _, ok := indices[w]; !ok {
				strongconnect(w)
				if low[w] < low[v] {
					low[v] = low[w]
				}
			} else if onStack[w] {
				if indices[w] < low[v] {
					low[v] = indices[w]
				}
			}
		}

		if low[v] == indices[v] {
			var scc []string
			for {
				w := stack[len(stack)-1]
				stack = stack[:len(stack)-1]
				onStack[w] = false
				scc = append(scc, w)
				if w == v {
					break
				}
			}
			sccs = append(sccs, scc)
		}
	}

	names := make([]string, 0, len(spec.Jobs))
	for _, job := range spec.Jobs {
		names = append(names, job.Name)
	}
	sort.Strings(names)
	for _, name := range names {
		if _, ok := indices[name]; !ok {
			strongconnect(name)
		}
	}

	cyclicSCC := map[string]bool{}
	var start string
	for _, scc := range sccs {
		if len(scc) > 1 {
			sorted := append([]string(nil), scc...)
			sort.Strings(sorted)
			for _, n := range sorted {
				cyclicSCC[n] = true
			}
			if start == "" || sorted[0] < start {
				start = sorted[0]
			}
		}
	}

	if start == "" {
		return nil
	}

	inStartSCC := map[string]bool{}
	for _, scc := range sccs {
		if len(scc) > 1 {
			for _, n := range scc {
				if n == start {
					for _, n2 := range scc {
						inStartSCC[n2] = true
					}
					break
				}
			}
		}
	}

	path := findCyclePath(start, adj, inStartSCC)
	return &ValidationError{Code: "cycle", Message: path}
}

func findCyclePath(start string, adj map[string][]string, inSCC map[string]bool) string {
	path := []string{start}
	visited := map[string]bool{}

	var dfs func() bool
	dfs = func() bool {
		cur := path[len(path)-1]
		for _, next := range adj[cur] {
			if !inSCC[next] {
				continue
			}
			if next == start {
				path = append(path, start)
				return true
			}
			if visited[next] {
				continue
			}
			visited[next] = true
			path = append(path, next)
			if dfs() {
				return true
			}
			path = path[:len(path)-1]
			delete(visited, next)
		}
		return false
	}

	if dfs() {
		return strings.Join(path, " -> ")
	}
	return start
}
