package main

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"syscall"
)

type jobResult struct {
	Name     string
	Status   string
	ExitCode int
	Stdout   string
	Stderr   string
}

func runSpec(spec *Spec, onFailure string, resultsPath string) int {
	levels := computeLevels(spec)
	order := make([]*Job, 0, len(spec.Jobs))
	for _, names := range levels {
		for _, name := range names {
			order = append(order, spec.ByName[name])
		}
	}

	results := make([]jobResult, len(order))
	statuses := map[string]string{}
	shortCircuit := false

	for i, job := range order {
		results[i].Name = job.Name

		if shortCircuit {
			results[i].Status = "skipped"
			results[i].ExitCode = -1
			results[i].Stdout = ""
			results[i].Stderr = ""
			statuses[job.Name] = "skipped"
			continue
		}

		skip := false
		for _, dep := range job.Deps {
			if statuses[dep] != "ok" {
				skip = true
				break
			}
		}
		if skip {
			results[i].Status = "skipped"
			results[i].ExitCode = -1
			results[i].Stdout = ""
			results[i].Stderr = ""
			statuses[job.Name] = "skipped"
			continue
		}

		stdout, stderr, exitCode := runJob(job)
		results[i].Stdout = stdout
		results[i].Stderr = stderr
		results[i].ExitCode = exitCode

		if exitCode == 0 {
			results[i].Status = "ok"
			statuses[job.Name] = "ok"
		} else {
			results[i].Status = "failed"
			statuses[job.Name] = "failed"
			if onFailure == "stop" {
				shortCircuit = true
			}
		}
	}

	if resultsPath != "" {
		if err := writeResults(resultsPath, onFailure, results); err != nil {
			fmt.Fprintf(os.Stderr, "error: results_write: %s\n", err)
			return 2
		}
	}

	for _, r := range results {
		if r.Status != "ok" {
			return 1
		}
	}
	return 0
}

func runJob(job *Job) (string, string, int) {
	cmd := exec.Command("bash", "-c", job.Command)
	cmd.Dir = job.Workdir

	envMap := map[string]string{}
	for _, kv := range os.Environ() {
		if idx := strings.IndexByte(kv, '='); idx >= 0 {
			envMap[kv[:idx]] = kv[idx+1:]
		}
	}
	for k, v := range job.Env {
		envMap[k] = v
	}
	envMap["JOBFORGE_JOB_NAME"] = job.Name
	resolvedWorkdir, err := filepath.Abs(job.Workdir)
	if err != nil {
		resolvedWorkdir = job.Workdir
	}
	envMap["JOBFORGE_JOB_WORKDIR"] = resolvedWorkdir

	env := make([]string, 0, len(envMap))
	for k, v := range envMap {
		env = append(env, k+"="+v)
	}
	sort.Strings(env)
	cmd.Env = env

	var stdoutBuf, stderrBuf bytes.Buffer
	cmd.Stdout = &stdoutBuf
	cmd.Stderr = &stderrBuf

	err = cmd.Run()
	if err != nil && cmd.ProcessState == nil {
		return sanitizeOutput(stdoutBuf.Bytes()), sanitizeOutput(stderrBuf.Bytes()), 127
	}
	exitCode := 0
	if cmd.ProcessState != nil {
		exitCode = exitCodeFromProcessState(cmd.ProcessState)
	}
	return sanitizeOutput(stdoutBuf.Bytes()), sanitizeOutput(stderrBuf.Bytes()), exitCode
}

func exitCodeFromProcessState(ps *os.ProcessState) int {
	if status, ok := ps.Sys().(syscall.WaitStatus); ok {
		if status.Exited() {
			return status.ExitStatus()
		}
		if status.Signaled() {
			return 128 + int(status.Signal())
		}
	}
	return ps.ExitCode()
}

func sanitizeOutput(b []byte) string {
	return strings.ToValidUTF8(string(b), "\ufffd")
}

func writeResults(path, onFailure string, results []jobResult) error {
	var b bytes.Buffer
	b.WriteString("{\n")
	b.WriteString("  \"on_failure\": \"")
	b.WriteString(onFailure)
	b.WriteString("\",\n")
	b.WriteString("  \"jobs\": [")
	if len(results) == 0 {
		b.WriteString("]\n")
	} else {
		b.WriteString("\n")
		for i, r := range results {
			b.WriteString("    {\n")
			b.WriteString("      \"name\": \"")
			writeJSONString(&b, r.Name)
			b.WriteString("\",\n")
			b.WriteString("      \"status\": \"")
			b.WriteString(r.Status)
			b.WriteString("\",\n")
			b.WriteString("      \"exit_code\": ")
			b.WriteString(strconv.Itoa(r.ExitCode))
			b.WriteString(",\n")
			b.WriteString("      \"stdout\": \"")
			writeJSONString(&b, r.Stdout)
			b.WriteString("\",\n")
			b.WriteString("      \"stderr\": \"")
			writeJSONString(&b, r.Stderr)
			b.WriteString("\"\n")
			b.WriteString("    }")
			if i < len(results)-1 {
				b.WriteString(",")
			}
			b.WriteString("\n")
		}
		b.WriteString("  ]\n")
	}
	b.WriteString("}\n")
	return os.WriteFile(path, b.Bytes(), 0644)
}

func writeJSONString(b *bytes.Buffer, s string) {
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\b':
			b.WriteString(`\b`)
		case '\t':
			b.WriteString(`\t`)
		case '\n':
			b.WriteString(`\n`)
		case '\f':
			b.WriteString(`\f`)
		case '\r':
			b.WriteString(`\r`)
		default:
			if c < 0x20 {
				b.WriteString(fmt.Sprintf(`\u00%02x`, c))
			} else {
				b.WriteByte(c)
			}
		}
	}
}
